/**
 * `data/items/itemCategories.json` as generated by `scripts/wow_items/categories.py` (**GENERATED**
 * by `python -m scripts.wow_items.categories`; never hand-edit it).
 *
 * Keys are `"<item class>.<subclass>"` (the game's ids, e.g. `"0.1"` = Consumable, Potions) plus
 * `"gear"` for every weapon and armor piece. `subclasses` names each key that has items (not `gear`);
 * `items` lists each key's item ids, sorted. Quest and Key items and obsolete subclasses are left out.
 */
export interface ItemCategoriesFile {
  source: string;
  clientBuild: string;
  attribution: string;
  subclasses: Readonly<Record<string, string>>;
  items: Readonly<Record<string, readonly number[]>>;
}
